import{d as p,C as t,o as d,c as h,a3 as s,E as e,j as n,a as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第四章","description":"《正易心法》第四章——《易》道不传，乃有周孔：上古卦画明则道行，后世卦画不明则道晦；学者执辞忘象，只作八字说，此谓之买椟还珠。","frontmatter":{"title":"正易心法·第四章","description":"《正易心法》第四章——《易》道不传，乃有周孔：上古卦画明则道行，后世卦画不明则道晦；学者执辞忘象，只作八字说，此谓之买椟还珠。","category":"guide","aliases":["正易心法第四章","易道不传乃有周孔","买椟还珠"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-04.md","filePath":"yijing/zheng-yi-xin-fa/chapter-04.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-04.md"},x=p({...c,setup(u){const i=[{id:"z4-01",label:"一、道不传乃有周孔",showLabel:!0,sentences:[["《易》道",{text:"不传",glossary:"buzhuan"},"，乃有周、孔。周、孔",{text:"孤行",glossary:"guxing"},"，《易》道",{text:"复晦",glossary:"fuhui"},"。"]],note:["《易》道失传，才不得已有了周文王和孔子的文字；而周孔之辞孤立地流行，《易》道反而再度晦暗。「不传」指卦画之学失传，不是文字失传——文字恰恰因为卦画失传才有了用武之地。"]},{id:"z4-02",label:"二、卦画明则道行",showLabel:!0,sentences:[["上古卦画明，《易》道行。后世卦画不明，《易》道不传。"]],note:["上古时代卦画清明，《易》道畅行于天下；后世卦画之学不再明了，《易》道于是失传。（这一句是全书的历史判断：道之明晦，全系于卦画之明不明，与文字多寡无关。）"]},{id:"z4-03",label:"三、不得已而有辞",showLabel:!0,sentences:[["圣人于是",{text:"不得已",glossary:"budeyi"},"而",{text:"有辞",glossary:"youci"},"。"]],note:["圣人（文王、孔子）迫不得已，才立下文字辞句。「不得已」三字是极微妙的定性：麻衣并不否定文王、孔子，而是说他们知道卦画才是本体，只因面对「卦画不明」的时代，不得不用文字来补救——错不在圣人，错在后人把补救手段当成了目的。"]},{id:"z4-04",label:"四、学者浅识",showLabel:!0,sentences:[["学者",{text:"浅识",glossary:"qianshi"},"，一著其辞，便谓《易》止于是，而周、孔遂自孤行。"]],note:["然而后世学者见识浅薄，一旦接触到这些文辞，便以为《易》不过如此，于是周孔之辞便孤立地流传。（「一著其辞」的「著」是接触、着眼于；辞本为「药方」，后人却把药方当饭吃。）"]},{id:"z4-05",label:"五、只作八字说",showLabel:!0,sentences:[["更不知有卦画",{text:"微旨",glossary:"weizhi"},"，只作",{text:"八字说",glossary:"baziShuo"},"。"]],note:["更不知道卦画还有精微的旨意，只用几个字来解说卦义。（「八字」指「乾健、坤顺、震动、巽入、坎陷、离丽、艮止、兑说」这八个字，出自《说卦传》。麻衣的批评是：这八个字是**结果**，卦画结构才是**原因**——乾为什么健？因为六爻皆阳；坎为什么陷？因为一阳陷于二阴之中。执果忘因，是为浅识。）"]},{id:"z4-06",label:"六、买椟还珠",showLabel:!0,sentences:[["此谓之",{text:"买椟还珠",glossary:"maiduHuanzhu"},"，由汉以来皆然，《易》道",{text:"胡为",glossary:"huwei"},"而不晦也？"]],note:["这就叫做「买椟还珠」——自汉代以来都是如此，《易》道怎么能不晦暗呢？（典出《韩非子》：买下装珠的木匣，却把珍珠退还。此处「椟」是周孔文辞，「珠」是卦画微旨。）"]}],o=[{id:"buzhuan",term:"不传",pinyin:"bù chuán",meaning:"不能流传、失传。此处指卦画之学失传，不是文字失传。"},{id:"guxing",term:"孤行",pinyin:"gū xíng",meaning:"单独运行、孤立存在。周孔之辞脱离卦画而独立流传。"},{id:"fuhui",term:"复晦",pinyin:"fù huì",meaning:"再度晦暗。晦是隐没不明，复是再次。"},{id:"budeyi",term:"不得已",pinyin:"bù dé yǐ",meaning:"迫不得已。强调文字是补救手段，非本意。"},{id:"youci",term:"有辞",pinyin:"yǒu cí",meaning:"立下文字辞句。指文王卦辞爻辞、孔子十翼。"},{id:"qianshi",term:"浅识",pinyin:"qiǎn shí",meaning:"见识浅薄。批评后世学者不识卦画本旨。"},{id:"weizhi",term:"微旨",pinyin:"wēi zhǐ",meaning:"精微的旨意。指卦画深层含义，非表面文字可达。"},{id:"baziShuo",term:"八字说",pinyin:"bā zì shuō",meaning:"只作八个字解释。指仅以「乾健坤顺」等简单标签论卦（语出《说卦传》），是执果忘因。"},{id:"maiduHuanzhu",term:"买椟还珠",pinyin:"mǎi dú huán zhū",meaning:"《韩非子》寓言：买下装珠的木匣，却退还珍珠。喻舍本逐末。此处「椟」是周孔文辞，「珠」是卦画微旨。"},{id:"huwei",term:"胡为",pinyin:"hú wéi",meaning:"为何、怎么。反问语气。"}];return(b,a)=>{const l=t("DaoTextReading"),r=t("DaoKeywordCards");return d(),h("div",null,[a[0]||(a[0]=s("",17)),e(l,{colophon:"乃有周孔 · 周孔孤行 · 不得已而有辞 · 买椟还珠",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第四章原文",sections:i,glossary:o}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[g("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"不得已",pinyin:["bù","dé","yǐ"],meaning:"迫不得已。强调文字是补救手段，非本意——麻衣批的是执辞忘象的后人，不是文王、孔子。"},{term:"八字说",pinyin:["bā","zì"],meaning:"乾健、坤顺、震动、巽入、坎陷、离丽、艮止、兑说八个字（出自《说卦传》）。麻衣说它是「果」不是「因」。"},{term:"买椟还珠",pinyin:["mǎi","dú","huán","zhū"],meaning:"《韩非子》寓言：买下装珠的木匣，却退还珍珠。「椟」是周孔文辞，「珠」是卦画微旨。"},{term:"微旨",pinyin:["wēi","zhǐ"],meaning:"精微的旨意。指卦画深层含义，非表面文字可达。"}]}),a[3]||(a[3]=s("",24))])}}});export{y as __pageData,x as default};
